        Evidence.PtAdd(pts, x0, y0, Evidence.PoMove());
        Evidence.PtAdd(pts, x1, y0, Evidence.PoLine());
        Evidence.PtAdd(pts, x1, y1, Evidence.PoLine());
        Evidence.PtAdd(pts, x0, y1, Evidence.PoLine());
        Evidence.PtAdd(pts, x0, y0, Evidence.PoClose());
        Evidence.PaSet(pa, r, Evidence.PfFlags(), Evidence.PgStroked());
        Evidence.PaSet(pa, r, Evidence.PfStroke(), stroke);
        Evidence.PaSet(pa, r, Evidence.PfWidth(), width);
        Evidence.PaSet(pa, r, Evidence.PfPfirst(), first);
        Evidence.PaSet(pa, r, Evidence.PfPcount(), 5);
