    }
    internal static int StStroke(emon.Port.Cells pa, emon.Port.Cells pts, int x0, int y0, int segs) {
        // An open stroked curve of `segs` Bezier segments from (x0, y0), 800 wide each and 1500 high; answers its row.
        int first = emon.Port.CellsLen(pts) / 3;
        int k = 0;
        int r = Evidence.PaNew(pa, 1, Evidence.PaCurve(), x0, y0, x0 + (segs * 800), y0 + 1500);
        Evidence.PtAdd(pts, x0, y0, Evidence.PoMove());
        while (k < segs) {
            Evidence.PtAdd(pts, x0 + (k * 800), y0 + 1500, Evidence.PoCurve());
            Evidence.PtAdd(pts, x0 + (k * 800) + 400, y0, Evidence.PoCurve());
            Evidence.PtAdd(pts, x0 + ((k + 1) * 800), y0 + 700, Evidence.PoCurve());
            k += 1;
        }
        Evidence.PaSet(pa, r, Evidence.PfFlags(), Evidence.PgStroked());
        Evidence.PaSet(pa, r, Evidence.PfStroke(), 2047903);
        Evidence.PaSet(pa, r, Evidence.PfWidth(), 140);
        Evidence.PaSet(pa, r, Evidence.PfPfirst(), first);
        Evidence.PaSet(pa, r, Evidence.PfPcount(), 1 + (segs * 3));
        return r;
    }
    internal static int StText(emon.Port.Cells fw, emon.Port.Cells gl, emon.Port.Cells et, int x, int y, int a, int b, int c) {
        // A word of up to three letters, 1200 high, at (x, y); answers its row.
        int ts = emon.Port.CellsLen(et);
        int n = 2;
        int g = Evidence.GlNew(gl, 1, x, y, x + 2400, y + 1200, a, ts, 1, 0);
        int w = Evidence.WdNew(fw, 1, x, y, x + 2400, y + 1200, x, y + 1000, x + 2400, y + 1000, 0, 0, ts, 2, 0, -1, -1);
        emon.Port.CellsPush(et, a);
        emon.Port.CellsPush(et, b);
        if (c > 0) {
            emon.Port.CellsPush(et, c);
            n = 3;
        }
        Evidence.WdSet(fw, w, 12, n);
        Evidence.WdSet(fw, w, Evidence.WfGfirst(), g);
        Evidence.WdSet(fw, w, Evidence.WfGcount(), 1);
        Evidence.GlSet(gl, g, Evidence.GfFill(), 1118481);
        return w;
    }
    [Xunit.Fact]
    public static void TestASignatureIsPenStrokesNearACue() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells sm = emon.Port.NewCells();
        StStroke(pa, pts, 10000, 20000, 4);
        StStroke(pa, pts, 10500, 20400, 1);
        // the cue `By:` just to the left, and another word elsewhere
        StText(fw, gl, et, 7200, 20300, 66, 121, 58);
        StText(fw, gl, et, 7200, 40000, 84, 111, 116);
        emon.Testport.AssertEq(StFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 1, "two strokes of five segments together and a cue beside them: a signature");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 5), Player.PlsSignature(), "a signature");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 1), 10000, "the box is the union of the strokes");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 3), 13200, "to the right edge of the longer");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 15), 2047903, "in blue");
        emon.Testport.AssertEq(Player.SlGet(sm, 0, 14), 0, "a signature has no text");
        // no cue: no signature
        emon.Port.CellsDrop(fw, 0);
        emon.Port.CellsDrop(et, 0);
        emon.Port.CellsDrop(gl, 0);
        StText(fw, gl, et, 7200, 20300, 84, 111, 116);
        emon.Testport.AssertEq(StFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 0, "without a cue word it is a curve in a figure");
        // a cue four line heights away is too far
        emon.Port.CellsDrop(fw, 0);
        emon.Port.CellsDrop(et, 0);
        emon.Port.CellsDrop(gl, 0);
        StText(fw, gl, et, 7200, 30000, 66, 121, 58);
        emon.Testport.AssertEq(StFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 0, "a cue far above is none");
    }
    [Xunit.Fact]
    public static void TestStrokesOfTwoInksAreAChartsCurvesAndNoSignature() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells sm = emon.Port.NewCells();
        // P12.7 (smoke B N3): a chart's curves and its legend's line samples, in a blue, a red and a green, merged into one cluster that a cue near it made a signature (the typed name the label under the legend). One pen
        // has one ink: the same two strokes in two inks are no signature, in one they are (the law above).
        StStroke(pa, pts, 10000, 20000, 4);
        int b = StStroke(pa, pts, 10500, 20400, 1);
        Evidence.PaSet(pa, b, Evidence.PfStroke(), 12591135);
        StText(fw, gl, et, 7200, 20300, 66, 121, 58);
        emon.Testport.AssertEq(StFind(pa, pts, gl, fw, et, cg, refs, ow, sm), 0, "a blue stroke and a red one together, with a cue beside them: a chart");
    }
    internal static int StOword(emon.Port.Cells ow, emon.Port.Cells et, int x, int y, int a, int b) {
        int ts = emon.Port.CellsLen(et);
        int w = Evidence.OwNew(ow, 1, x - 400, y - 300, x + 400, y + 300, x - 400, y + 300, x + 400, y + 300, 0, 0, ts, 2, 0, 800, -1);
        emon.Port.CellsPush(et, a);
        emon.Port.CellsPush(et, b);
        return w;
    }
    internal static int StOgroup(emon.Port.Cells cg, emon.Port.Cells refs, int oword) {
        int g = Player.CgNew(cg, 1, 0, 0, 100, 100, 0);
        int f = Evidence.RfAdd(refs, Evidence.EaOwords(), oword);
        Player.CgSet(cg, g, Player.CgfOfirst(), f);
        Player.CgSet(cg, g, Player.CgfOcount(), 1);
        return g;
    }
