    internal static int StBlock(emon.Port.Cells nodes, emon.Port.Cells regions, int parent, int page, int y0, int y1) {
        int n = Model.NodeNew(nodes, Model.NkParagraph(), parent);
        Model.NodeAddRegion(nodes, regions, n, page, 0, y0, 60000, y1);
        return n;
    }
    internal static int StSealRow(emon.Port.Cells sm, int page, int x0, int y0, int x1, int y1, int kind, int ink) {
        int o = Player.SlNew(sm, page, x0, y0, x1, y1, kind);
        emon.Port.CellsSet(sm, (o * 16) + 15, ink);
        return o;
    }
    [Xunit.Fact]
    public static void TestASealNodeIsWrittenAfterTheBlockItOverlaps() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells chk = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells sm = emon.Port.NewCells();
        emon.Port.Cells nn = emon.Port.NewCells();
        emon.Port.Cells na = emon.Port.NewCells();
        emon.Port.Cells nr = emon.Port.NewCells();
        emon.Port.Cells nm = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        int sec = Model.NodeNew(nodes, Model.NkSection(), 0);
        StBlock(nodes, regions, sec, 1, 10000, 20000);
        StBlock(nodes, regions, sec, 1, 30000, 40000);
        StBlock(nodes, regions, sec, 1, 50000, 60000);
        // S1 over the end of A and the start of B (as much of each: the later); S2 in the gap above C; S3 on page 9, after everything
        StSealRow(sm, 1, 20000, 15000, 50000, 35000, Player.PlsSeal(), 2047903);
        StSealRow(sm, 1, 20000, 42000, 50000, 48000, Player.PlsStamp(), 12591135);
        StSealRow(sm, 9, 0, 0, 100, 100, Player.PlsSignature(), -1);
        emon.Testport.AssertEq(Sealmark.SmWrite(sm, et, nodes, attrs, regions, text, nn, na, nr, nm), 3, "three seals were written");
        emon.Testport.AssertEq(Model.NodeCount(nn), 8, "three blocks, the section and the document are copied, and the three seals join them");
        emon.Testport.AssertEq(Model.NodeKind(nn, 0), Model.NkDocument(), "the document");
        emon.Testport.AssertEq(Model.NodeKind(nn, 1), Model.NkSection(), "its section");
        emon.Testport.AssertEq(Model.NodeKind(nn, 2), Model.NkParagraph(), "block A");
        emon.Testport.AssertEq(Model.NodeKind(nn, 3), Model.NkParagraph(), "block B");
        emon.Testport.AssertEq(Model.NodeKind(nn, 4), Model.NkSeal(), "the first seal is after B, the last block it overlaps");
        emon.Testport.AssertEq(Model.NodeSub(nn, 4), Model.SlSeal(), "a seal");
        emon.Testport.AssertEq(Model.NodeKind(nn, 5), Model.NkSeal(), "the second is before C: it overlaps none and C starts below its top");
        emon.Testport.AssertEq(Model.NodeSub(nn, 5), Model.SlStamp(), "a stamp");
        emon.Testport.AssertEq(Model.NodeKind(nn, 6), Model.NkParagraph(), "then block C");
        emon.Testport.AssertEq(Model.NodeKind(nn, 7), Model.NkSeal(), "the third, on a later page, is the last of the section");
        emon.Testport.AssertEq(Model.NodeParent(nn, 7), 1, "a child of the section");
        emon.Testport.AssertEq(Model.ModelCheck(nn, na, nr, text, pages, ledger, layout, chk), 0, "and the Model still checks");
    }
    internal static int StOwtext(emon.Port.Cells ow, emon.Port.Cells et, byte[] b, int conf) {
        // An OCR word of page 1 whose text is the bytes of `b`, the engine's confidence `conf`; answers its row.
        int ts = emon.Port.CellsLen(et);
        int n = emon.Port.BlobLen(b);
        int k = 0;
        while (k < n) {
            emon.Port.CellsPush(et, emon.Port.BlobU8(b, k));
            k += 1;
        }
        return Evidence.OwNew(ow, 1, 1000, 1000, 2000, 1600, 1000, 1600, 2000, 1600, 0, 0, ts, n, 0, conf, -1);
    }
    internal static int StPxgroup(emon.Port.Cells cg, emon.Port.Cells refs, int first, int count, int flags, int hue) {
        // A raster seal's group (`emon.sealpx`): its words are the OCR words first.. first + count - 1, in its box on page 1, its colour code in `rot`.
        int g = Player.CgNew(cg, 1, 1000, 1000, 7000, 7000, hue);
        int f = 0;
        int i = 0;
        while (i < count) {
            if (i == 0) {
                f = Evidence.RfAdd(refs, Evidence.EaOwords(), first + i);
            } else {
                Evidence.RfAdd(refs, Evidence.EaOwords(), first + i);
            }
            i += 1;
        }
        Player.CgSet(cg, g, Player.CgfOfirst(), f);
        Player.CgSet(cg, g, Player.CgfOcount(), count);
        Player.CgSet(cg, g, Player.CgfFlags(), flags);
        return g;
    }
